mapper.select:
SELECT ps.procurement_scheme_code, ps.procurement_scheme_name, ps.price_type, ps.subject_matter_type, ta.id tenderApplyId, null as twice_quot, su.thrid_org_name unit,tn.apply_time_notice,tn.attach_id_notice, tn.scheme_id, tn.id noticeId , tn.create_time, tn.contact, tn.apply_time, tn.notice_status, tn.vendor_range, tn.phone, CASE WHEN ta.id is null or ta.id = '' THEN '未报名' ELSE '已报名' END tenderApplyStatus FROM tb_tender_notice tn left join tb_tender_notice_range tnr on tnr.notice_id = tn.id and tnr.del_flag = 0 and tnr.type = 1 left join tb_procurement_scheme ps on ps.id = tn.scheme_id and ps.del_flag = 0 left join tb_tender_apply ta on ta.notice_id = tn.id and ta.del_flag = 0 and ta.vendor_id = #{queryDTO.vendorId} left join sys_user su on su.user_id = ps.procurement_officer
/* 在线报名只能显示 公开招标的数据，状态不做控制。 */ tn.del_flag = 0 and tn.notice_status != 0 and ps.procurement_type = 1 and ( CASE WHEN ps.procurement_type != 1 and tn.vendor_range = 1 THEN tnr.vendor_id = #{queryDTO.vendorId} ELSE 1 END) = 1
and ps.procurement_scheme_name like CONCAT('%', #{queryDTO.procurementSchemeName}, '%')
and ps.procurement_scheme_code = #{queryDTO.procurementSchemeCode}
order by tn.create_time desc

SELECT ps.procurement_scheme_code, ps.procurement_scheme_name, ps.price_type, ps.subject_matter_type, ta.id tenderApplyId, su.thrid_org_name unit,tn.apply_time_notice,tn.attach_id_notice, tn.scheme_id, tn.id noticeId , tn.create_time, tn.contact, tn.apply_time, tn.notice_status, tn.vendor_range, tn.phone, CASE WHEN ta.id is null or ta.id = '' THEN '未报名' ELSE '已报名' END tenderApplyStatus FROM tb_tender_notice tn left join tb_tender_notice_range tnr on tnr.notice_id = tn.id and tnr.del_flag = 0 and tnr.type = 1 left join tb_tender_apply ta on ta.notice_id = tn.id and ta.del_flag = 0 and ta.vendor_id = #{queryDTO.vendorId} left join tb_procurement_scheme ps on ps.id = tn.scheme_id and ps.del_flag = 0 left join sys_user su on su.user_id = ps.procurement_officer
tn.del_flag = 0 and tn.notice_status != 0 and ( CASE WHEN ps.procurement_type != 1 and tn.vendor_range = 1 THEN tnr.vendor_id = #{queryDTO.vendorId} ELSE 1 END) = 1
and ps.procurement_scheme_name like CONCAT('%', #{queryDTO.procurementSchemeName}, '%')
and ps.procurement_scheme_code = #{queryDTO.procurementSchemeCode}
/* 公开招标 的 在线投标不显示状态 为招标报名阶段的。只显示给已报名的供应商。 */ and ps.procurement_type = 1 and tn.notice_status!=11 and tn.notice_status!=12 and tn.notice_status!=13 and ta.approve_result = 1
/* 公开招标 的 在线投标不显示状态 为招标报名阶段的。 */ and ps.procurement_type != 1 and tn.notice_status!=11 and tn.notice_status!=12 and tn.notice_status!=13
order by tn.create_time desc

SELECT tn.id noticeId, ps.id schemeId, ps.procurement_scheme_code, ps.procurement_scheme_name, ps.procurement_plan_type, ps.price_type, ps.subject_matter_type, tn.create_time, tn.notice_status, su.thrid_org_name unit, ps.price_type, ps.subject_matter_type,ps.procurement_type, CASE WHEN ps.procurement_type = 1 then CASE WHEN (tn.notice_status = 11 or tn.notice_status = 12 or tn.notice_status = 13) then CASE WHEN (select update_after from tb_tender_notice_change_record where tn.id = notice_id and notice_status = 11 and type = 1 and del_flag = 0 order by id desc limit 1) IS NOT NULL THEN str_to_date((select update_after from tb_tender_notice_change_record where tn.id = notice_id and notice_status = 11 and type = 1 and del_flag = 0 order by id desc limit 1), '%Y-%m-%d %H:%i') ELSE tn.apply_time_notice END ELSE CASE WHEN (select update_after from tb_tender_notice_change_record where tn.id = notice_id and notice_status = 1 and type = 1 and del_flag = 0 order by id desc limit 1) IS NOT NULL THEN str_to_date((select update_after from tb_tender_notice_change_record where tn.id = notice_id and notice_status = 1 and type = 1 and del_flag = 0 order by id desc limit 1), '%Y-%m-%d %H:%i') ELSE tn.apply_time END END ELSE CASE WHEN (select update_after from tb_tender_notice_change_record where tn.id = notice_id and notice_status = 1 and type = 1 and del_flag = 0 order by id desc limit 1) IS NOT NULL THEN str_to_date((select update_after from tb_tender_notice_change_record where tn.id = notice_id and notice_status = 1 and type = 1 and del_flag = 0 order by id desc limit 1), '%Y-%m-%d %H:%i') ELSE tn.apply_time END END AS applyTime FROM tb_tender_notice tn LEFT JOIN tb_procurement_scheme ps ON ps.id = tn.scheme_id AND ps.del_flag = 0 left join tb_tender_notice_range tnr on tnr.notice_id = tn.id and tnr.del_flag = 0 and tnr.type = 1 left join sys_user su on su.user_id = ps.procurement_officer where tn.del_flag = 0 and (tn.notice_status = 11 or tn.notice_status = 12 or tn.notice_status = 13 or tn.notice_status = 1)
and ps.procurement_plan_type = #{queryDTO.procurementPlanType}
and ps.procurement_scheme_name like CONCAT('%', #{queryDTO.procurementSchemeName}, '%')
and ps.procurement_type = #{queryDTO.schemeType}
and ( CASE WHEN ps.procurement_type != 1 and tn.vendor_range = 1 THEN tnr.vendor_id = #{queryDTO.vendorId} ELSE 1 END) = 1
order by tn.create_time desc

SELECT ps.procurement_scheme_code, ps.procurement_scheme_name, tn.create_time, tn.notice_status, bi.twice_time, CASE WHEN bi2.id is null or bi.id = '' THEN '未二次报价' ELSE '已二次报价' END twiceBidStatus FROM tb_tender_notice tn inner join tb_procurement_scheme ps on ps.id = tn.scheme_id and ps.del_flag = 0 inner join tb_bidding_info bi on bi.notice_id = tn.id and bi.del_flag = 0 left join tb_bidding_info bi2 on bi2.parent_id = bi.id and bi2.del_flag = 0
tn.del_flag = 0 and bi.parent_id is null and bi.twice_quot = 1 and bi.vendor_id = #{queryDTO.vendorId}
and ps.procurement_scheme_name like CONCAT('%', #{queryDTO.procurementSchemeName}, '%')

select tn.id noticeId, br.id biddingResultId, br.bid_result, br.`rank`, br.sure_bid
from tb_tender_notice tn
left join tb_bidding_result br on br.notice_id = tn.id

    tn.del_flag = 0

        and tn.id = #{noticeId}


        and tn.notice_status = #{noticeStatus}


        and br.publicity_end_time < #{nowDate}


order by tn.id, br.`rank`

select tcps.id as splitContractId,tpp.id as planId,tcps.split_contract_name,tcp.contract_planning_name,tcp.contract_planning_code ,tcp.contract_planning_id
/* 合约规划拆分对象 */
from tb_contract_planning_split tcps
/* 采购计划对象 */
left join tb_procurement_plan tpp on tcps.procurement_plan_id = tpp.id and tpp.del_flag = 0
/* 合约规划对象 */
left join tb_contract_planning tcp on tcp.plan_id = tpp.id and tcp.del_flag = 0
where tcps.del_flag = 0 and tcp.contract_planning_code is not null and tcp.contract_planning_id is not null

    and tcp.contract_planning_code = #{queryVO.contractPlanningCode}


    and tcp.contract_planning_id = #{queryVO.contractPlanningId}


    and tcp.contract_planning_id in

        #{contractId,jdbcType=VARCHAR}

select ps.procurement_scheme_code, ps.procurement_scheme_name, br.notifi_time, br.notifi_content, br.id biddingResultId, br.scheme_id, tn.id noticeId from tb_tender_notice tn inner join tb_bidding_result br on br.notice_id = tn.id left join tb_procurement_scheme ps on ps.id = br.scheme_id
tn.del_flag = 0 and br.del_flag = 0 and br.bid_result = 1 and br.send_notified = 1
and tn.notice_status = #{queryVO.noticeStatus}
and br.vendor_id = #{queryVO.vendorId}
and ps.procurement_scheme_name like CONCAT('%', #{queryVO.procurementSchemeName}, '%')
order by br.notifi_time desc

select tn.id,mp.min_project_id as project_id,ps.id as scheme_id, ps.procurement_type as scheme_type,tn.contact,
       tn.phone,tn.email,tn.attach_id_notice,tn.apply_time_notice
from tb_tender_notice tn
inner join tb_procurement_scheme ps on ps.id = tn.scheme_id
inner join tb_min_project mp on mp.min_account_code = ps.project_code

    tn.del_flag = 0 and ps.del_flag = 0 and tn.notice_status != 0 and ps.procurement_type = 1

        and tn.id = #{queryVO.id}


        and tn.create_time >= #{queryVO.startTime}


        and tn.create_time <= #{queryVO.endTime}


order by tn.create_time desc
